function a(i,t=0){const n=Number(t)||0;return Math.round(i*(1-n/100))}function c(i,t){const n=Number(i)||0;if(!t)return{original:n,final:n,savings:0};if(t.discountFixed!=null&&Number(t.discountFixed)>0){const e=Math.min(n,Math.round(Number(t.discountFixed)));return{original:n,final:Math.max(0,n-e),savings:e}}const s=Number(t.discountPercent)||0,r=a(n,s);return{original:n,final:r,savings:n-r}}export{c as a};
